// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', function() {
  initializeDashboard();
});

function initializeDashboard() {
  // Hide loading overlay after a delay
  setTimeout(() => {
    const loadingOverlay = document.getElementById('loading-overlay');
    const progressBar = document.getElementById('progress-bar');
    const loadingStatus = document.getElementById('loading-status');
    
    // Simulate loading progress
    let progress = 0;
    const loadingSteps = [
      'Loading tectonic data...',
      'Loading climate data...',
      'Loading population data...',
      'Loading economic data...',
      'Loading environmental data...',
      'Initializing globe...',
      'Calibrating sensors...',
      'Starting simulation...'
    ];
    
    let stepIndex = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress > 100) progress = 100;
      progressBar.style.width = `${progress}%`;
      
      if (progress > (stepIndex + 1) * (100 / loadingSteps.length) && stepIndex < loadingSteps.length - 1) {
        stepIndex++;
        loadingStatus.textContent = loadingSteps[stepIndex];
      }
      
      if (progress >= 100) {
        clearInterval(progressInterval);
        setTimeout(() => {
          loadingOverlay.classList.add('hidden');
          startSimulation();
        }, 500);
      }
    }, 200);
  }, 1000);
}

function startSimulation() {
  // Populate tickers
  populateTickers();
  
  // Populate lists
  populateEarthquakes();
  populateVolcanoes();
  populateConflicts();
  
  // Generate charts
  generateTradeRoutes();
  generateAgePyramid();
  generateReligionChart();
  
  // Populate detailed table
  populateDetailedTable();
  
  // Start data refresh interval
  state.dataRefreshInterval = setInterval(updateData, 5000);
  
  // Start simulation time
  updateSimulationTime();
  setInterval(updateSimulationTime, 1000);
  
  // Initialize globe
  initializeGlobe();
  
  // Setup tab switching
  setupTabSwitching();
}

function populateTickers() {
  const globalTicker = document.getElementById('global-ticker-content');
  const secondaryTicker = document.getElementById('secondary-ticker-content');
  
  // Duplicate content for seamless loop
  globalTicker.innerHTML = globalTickerData + globalTickerData;
  secondaryTicker.innerHTML = secondaryTickerData + secondaryTickerData;
  
  // Start ticker animation
  animateTicker(globalTicker, 120000);
  animateTicker(secondaryTicker, 180000);
}

function animateTicker(element, duration) {
  let startTime = null;
  
  function animate(timestamp) {
    if (!startTime) startTime = timestamp;
    const progress = timestamp - startTime;
    const percentage = (progress % duration) / duration;
    
    element.style.transform = `translateX(-${percentage * 50}%)`;
    
    requestAnimationFrame(animate);
  }
  
  requestAnimationFrame(animate);
}

function populateEarthquakes() {
  const list = document.getElementById('earthquake-list');
  list.innerHTML = earthquakeData.map(eq => `
    <li>
      <span>M${eq.mag} - ${eq.location}</span>
      <span>${eq.time}</span>
    </li>
  `).join('');
}

function populateVolcanoes() {
  const list = document.getElementById('volcano-list');
  list.innerHTML = volcanoData.map(v => `
    <li>
      <span>${v.name}</span>
      <span style="color: ${v.alert === 'Red' ? '#ef4444' : '#fbbf24'}">${v.status}</span>
    </li>
  `).join('');
}

function populateConflicts() {
  const list = document.getElementById('conflict-list');
  list.innerHTML = conflictData.map(c => `
    <li>
      <span>${c.region}</span>
      <span style="color: ${c.intensity === 'High' ? '#ef4444' : c.intensity === 'Medium' ? '#fbbf24' : '#10b981'}">${c.intensity}</span>
    </li>
  `).join('');
}

function generateTradeRoutes() {
  const svg = document.getElementById('trade-svg');
  if (!svg) return;
  
  // Simple trade route visualization
  const routes = [
    { x1: 20, y1: 30, x2: 80, y2: 20, volume: 'high' },
    { x1: 80, y1: 20, x2: 30, y2: 70, volume: 'medium' },
    { x1: 30, y1: 70, x2: 70, y2: 40, volume: 'low' },
    { x1: 70, y1: 40, x2: 50, y2: 60, volume: 'high' },
    { x1: 50, y1: 60, x2: 20, y2: 30, volume: 'medium' },
  ];
  
  svg.innerHTML = routes.map(route => `
    <line x1="${route.x1}" y1="${route.y1}" x2="${route.x2}" y2="${route.y2}" 
          stroke="${route.volume === 'high' ? '#ff6b6b' : route.volume === 'medium' ? '#ffd93d' : '#6bcf7f'}"
          stroke-width="${route.volume === 'high' ? 3 : route.volume === 'medium' ? 2 : 1}"
          opacity="0.7">
      <animate attributeName="stroke-dasharray" values="0,100;100,0" dur="3s" repeatCount="indefinite" />
    </line>
  `).join('');
}

function generateAgePyramid() {
  const container = document.getElementById('age-pyramid');
  if (!container) return;
  
  const ageGroups = [
    { age: '0-14', male: 25, female: 24 },
    { age: '15-24', male: 16, female: 15 },
    { age: '25-54', male: 40, female: 39 },
    { age: '55-64', male: 12, female: 13 },
    { age: '65+', male: 7, female: 9 },
  ];
  
  let html = '<svg viewBox="0 0 100 100" style="width:100%;height:100%">';
  
  ageGroups.forEach((group, i) => {
    const y = i * 20;
    const maleWidth = group.male * 0.8;
    const femaleWidth = group.female * 0.8;
    
    html += `
      <text x="5" y="${y + 12}" font-size="4" fill="#94a3b8">${group.age}</text>
      <rect x="10" y="${y}" width="${maleWidth}" height="16" fill="#38bdf8" opacity="0.7"/>
      <rect x="${100 - 10 - femaleWidth}" y="${y}" width="${femaleWidth}" height="16" fill="#f472b6" opacity="0.7"/>
      <text x="${10 + maleWidth + 2}" y="${y + 12}" font-size="3" fill="#94a3b8">${group.male}%</text>
      <text x="${100 - 10 - femaleWidth - 15}" y="${y + 12}" font-size="3" fill="#94a3b8">${group.female}%</text>
    `;
  });
  
  html += '</svg>';
  container.innerHTML = html;
}

function generateReligionChart() {
  const container = document.getElementById('religion-chart');
  if (!container) return;
  
  const religions = [
    { name: 'Christianity', pct: 31, color: '#38bdf8' },
    { name: 'Islam', pct: 25, color: '#fbbf24' },
    { name: 'Hinduism', pct: 15, color: '#f472b6' },
    { name: 'Buddhism', pct: 7, color: '#a78bfa' },
    { name: 'Folk', pct: 6, color: '#34d399' },
    { name: 'Unaff.', pct: 16, color: '#94a3b8' },
  ];
  
  let html = '<svg viewBox="0 0 100 100" style="width:100%;height:100%">';
  
  let currentAngle = 0;
  religions.forEach(rel => {
    const angle = (rel.pct / 100) * 360;
    const largeArc = angle > 180 ? 1 : 0;
    const endAngle = currentAngle + angle;
    
    const x1 = 50 + 40 * Math.cos(Math.PI * currentAngle / 180);
    const y1 = 50 + 40 * Math.sin(Math.PI * currentAngle / 180);
    const x2 = 50 + 40 * Math.cos(Math.PI * endAngle / 180);
    const y2 = 50 + 40 * Math.sin(Math.PI * endAngle / 180);
    
    html += `
      <path d="M 50 50 L ${x1} ${y1} A 40 40 0 ${largeArc} 1 ${x2} ${y2} Z"
            fill="${rel.color}" opacity="0.7">
        <title>${rel.name}: ${rel.pct}%</title>
      </path>
    `;
    
    currentAngle = endAngle;
  });
  
  html += '</svg>';
  container.innerHTML = html;
}

