function updateData() {
  // Simulate data updates with small random changes
  const updateValue = (id, baseValue, variation = 0.01) => {
    const elem = document.getElementById(id);
    if (elem) {
      const current = parseFloat(elem.textContent.replace(/[^0-9.-]/g, ''));
      const change = (Math.random() - 0.5) * baseValue * variation;
      const newValue = Math.max(0, current + change);
      
      if (id.includes('pop') || id.includes('count')) {
        elem.textContent = Math.floor(newValue).toLocaleString();
      } else if (id.includes('gdp') || id.includes('value') || id.includes('tons') || id.includes('barrels')) {
        elem.textContent = newValue.toFixed(1).toLocaleString();
      } else if (id.includes('temp') || id.includes('rate') || id.includes('pct')) {
        elem.textContent = newValue.toFixed(1) + (id.includes('temp') ? '°C' : id.includes('rate') ? '%' : '');
      } else if (id.includes('date')) {
        // Update simulation time
        state.simulationTime = new Date(state.simulationTime.getTime() + 3600000 * state.simulationSpeed);
        elem.textContent = state.simulationTime.toISOString().split('T')[0];
      } else {
        elem.textContent = newValue.toFixed(1);
      }
    }
  };
  
  // Update various data points
  updateValue('global-pop', 8123456789);
  updateValue('global-gdp', 105.2);
  updateValue('global-temp', 1.2);
  updateValue('sea-level', 3.3);
  updateValue('active-volcanoes', 43);
  updateValue('earthquakes-24h', 312);
  updateValue('active-storms', 47);
  updateValue('hurricanes', 12);
  updateValue('cyclones', 15);
  
  // Update simulation time display
  const timeElem = document.getElementById('current-time');
  if (timeElem) {
    const simTime = new Date(state.simulationTime.getTime() + 3600000 * state.simulationSpeed);
    timeElem.textContent = simTime.toISOString().replace('T', ' ').substring(0, 19) + ' UTC';
  }
}

function updateSimulationTime() {
  state.simulationTime = new Date(state.simulationTime.getTime() + 3600000 * state.simulationSpeed);
  
  const dateOverlay = document.getElementById('current-date-overlay');
  const simSpeed = document.getElementById('sim-speed-overlay');
  
  if (dateOverlay) {
    dateOverlay.textContent = state.simulationTime.toISOString().split('T')[0];
  }
  
  if (simSpeed) {
    simSpeed.textContent = `SPEED: ${state.simulationSpeed}x`;
  }
}

function initializeGlobe() {
  const canvas = document.getElementById('globe-canvas');
  if (!canvas) return;
  
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.offsetWidth;
  const height = canvas.height = canvas.offsetHeight;
  
  // Simple rotating globe animation
  let rotation = 0;
  
  function drawGlobe() {
    ctx.clearRect(0, 0, width, height);
    
    // Draw globe
    const centerX = width / 2;
    const centerY = height / 2;
    const radius = Math.min(width, height) / 2 - 20;
    
    // Globe background
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
    const gradient = ctx.createRadialGradient(centerX - radius/3, centerY - radius/3, 0, centerX, centerY, radius);
    gradient.addColorStop(0, '#1e293b');
    gradient.addColorStop(1, '#0f172a');
    ctx.fillStyle = gradient;
    ctx.fill();
    
    // Globe grid
    ctx.strokeStyle = 'rgba(56, 189, 248, 0.2)';
    ctx.lineWidth = 1;
    
    // Latitude lines
    for (let i = 0; i < 6; i++) {
      const y = centerY - radius/2 + (i * radius/5);
      ctx.beginPath();
      ctx.ellipse(centerX, centerY, radius * Math.cos(Math.asin((y - centerY) / radius)), radius * Math.abs(Math.sin(Math.asin((y - centerY) / radius))), 0, 0, Math.PI * 2);
      ctx.stroke();
    }
    
    // Longitude lines (rotating)
    for (let i = 0; i < 8; i++) {
      const angle = (i * Math.PI / 4) + rotation;
      ctx.beginPath();
      ctx.moveTo(centerX + radius * Math.cos(angle), centerY);
      ctx.quadraticCurveTo(
        centerX + radius * Math.cos(angle) * 0.7,
        centerY + radius * 0.3,
        centerX + radius * Math.cos(angle + Math.PI),
        centerY
      );
      ctx.stroke();
    }
    
    rotation += 0.005;
    requestAnimationFrame(drawGlobe);
  }
  
  drawGlobe();
}

function setupTabSwitching() {
  const tabBtns = document.querySelectorAll('.tab-btn');
  const tabContents = document.querySelectorAll('.tab-content');
  
  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const tabId = btn.dataset.tab;
      
      // Remove active class from all
      tabBtns.forEach(b => b.classList.remove('active'));
      tabContents.forEach(c => c.classList.remove('active'));
      
      // Add active to clicked
      btn.classList.add('active');
      const targetTab = document.getElementById(`tab-${tabId}`);
      if (targetTab) {
        targetTab.classList.add('active');
      }
    });
  });
}

// Utility: Random number in range
function random(min, max) {
  return Math.random() * (max - min) + min;
}

// Utility: Format number with commas
function formatNumber(num) {
  return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

// Handle window resize for canvas
window.addEventListener('resize', () => {
  const canvas = document.getElementById('globe-canvas');
  if (canvas) {
    canvas.width = canvas.offsetWidth;
    canvas.height = canvas.offsetHeight;
  }
});

// Keyboard shortcuts
document.addEventListener('keydown', (e) => {
  if (e.key === ' ') {
    // Space bar to pause/resume
    state.isRunning = !state.isRunning;
    if (state.isRunning) {
      startSimulation();
    } else {
      clearInterval(state.dataRefreshInterval);
    }
  } else if (e.key === 'ArrowUp') {
    // Increase speed
    state.simulationSpeed = Math.min(10, state.simulationSpeed + 1);
    updateSimulationTime();
  } else if (e.key === 'ArrowDown') {
    // Decrease speed
    state.simulationSpeed = Math.max(1, state.simulationSpeed - 1);
    updateSimulationTime();
  }
});

